import React from 'react';
import { View, Text, StatusBar, TouchableOpacity } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';

const Container = styled.View`
  flex: 1;
  background-color: ${colors.secondary};
`;

const Header = styled.View`
  height: 60px;
  background-color: ${colors.secondary};
  justify-content: center;
  align-items: center;
  border-bottom-width: 1px;
  border-bottom-color: #333;
`;

const HeaderTitle = styled.Text`
  color: ${colors.textSecondary};
  font-size: 18px;
  font-weight: 500;
`;

const Content = styled.View`
  flex: 1;
  background-color: ${colors.white};
  border-top-left-radius: 30px;
  border-top-right-radius: 30px;
  padding: ${spacing.xl}px;
  align-items: center;
`;

const Display = styled.View`
  margin-vertical: ${spacing.xl}px;
  align-items: center;
`;

const ValueLabel = styled.Text`
  font-size: 24px;
  font-weight: bold;
  color: ${colors.secondary};
  margin-bottom: ${spacing.xs}px;
`;

const ValueText = styled.Text`
  font-size: 48px;
  font-weight: bold;
  color: ${colors.primary};
`;

const StatsGrid = styled.View`
  width: 100%;
  margin-top: ${spacing.lg}px;
`;

const StatItem = styled.View`
  flex-direction: row;
  justify-content: space-between;
  padding-vertical: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: ${colors.border};
`;

const StatLabel = styled.Text`
  font-size: 18px;
  color: ${colors.textSecondary};
  font-weight: 500;
`;

const StatValue = styled.Text`
  font-size: 20px;
  font-weight: bold;
  color: ${colors.secondary};
`;

const StartButton = styled.TouchableOpacity`
  background-color: #008b8b; /* Teal as seen in original image */
  width: 100%;
  height: 60px;
  border-radius: 30px;
  justify-content: center;
  align-items: center;
  margin-top: auto;
  margin-bottom: ${spacing.xl}px;
`;

const StartButtonText = styled.Text`
  color: ${colors.white};
  font-size: 22px;
  font-weight: bold;
  letter-spacing: 1px;
`;

import { useNavigation } from '@react-navigation/native';

const TaximeterScreen = () => {
    const navigation = useNavigation();

    return (
        <Container>
            <StatusBar barStyle="light-content" backgroundColor={colors.secondary} />

            <Header>
                <TouchableOpacity onPress={() => navigation.goBack()} style={{ position: 'absolute', left: 15 }}>
                    <Icon name="arrow-back" size={28} color={colors.white} />
                </TouchableOpacity>
                <HeaderTitle>Taxímetro</HeaderTitle>
            </Header>

            <Content>
                <Display>
                    <ValueLabel>VALOR R$</ValueLabel>
                    <ValueText>0,00</ValueText>
                </Display>

                <StatsGrid>
                    <StatItem>
                        <StatLabel>TEMPO</StatLabel>
                        <StatValue>0</StatValue>
                    </StatItem>
                    <StatItem>
                        <StatLabel>DISTÂNCIA</StatLabel>
                        <StatValue>0 KM</StatValue>
                    </StatItem>
                    <StatItem>
                        <StatLabel>TAXA BASE R$</StatLabel>
                        <StatValue>0,00</StatValue>
                    </StatItem>
                </StatsGrid>

                <StartButton activeOpacity={0.8}>
                    <StartButtonText>INICIAR</StartButtonText>
                </StartButton>
            </Content>
        </Container>
    );
};

export default TaximeterScreen;
